package de.schaepi.puls180;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.time.*;import java.util.*;import java.io.*;
/** Validated, merge-only restore. Database changes commit together; preferences are replayable. */
public final class AppBackup {
 private static void require(boolean value)throws IOException{if(!value)throw new IOException("Ungültige Sicherungsdaten");}
 public static JSONObject read(InputStream input,String app)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){require(out.size()+n<=50*1024*1024);out.write(b,0,n);}JSONObject data=new JSONObject(out.toString("UTF-8"));validate(data,app);return data;}
 static void pressure(double sys,double dia)throws IOException{require(Double.isFinite(sys)&&Double.isFinite(dia)&&sys>dia&&dia>0&&sys<=400&&dia<=300);}
 static void time(String t)throws Exception{Instant date=Instant.parse(t);require(!date.isBefore(Instant.parse("1900-01-01T00:00:00Z"))&&!date.isAfter(Instant.parse("2201-01-01T00:00:00Z")));}
 static void key(String k)throws IOException{require(k.length()<512&&k.matches("[a-zA-Z0-9_.]+:[a-zA-Z0-9_.:-]+"));}
 public static void validate(JSONObject d,String app)throws Exception{
  require("schaepi-blutdruck-backup".equals(d.getString("format")));int version=d.getInt("version");require(version==1||version==2);require(app.equals(d.getString("app")));
  JSONArray rows=d.getJSONArray("measurements"),links=d.getJSONArray("folders"),direct=d.getJSONArray("directReadings"),hidden=d.getJSONArray("hidden"),heart=d.getJSONArray("loadedPulseValues");require(rows.length()<=100000&&links.length()<=200000&&direct.length()<=100000&&heart.length()<=1000000&&hidden.length()<=100000);
  Set<String> keys=new HashSet<>(),ids=new HashSet<>();
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String k=r.getString("key");key(k);require(keys.add(k));time(r.getString("time"));pressure(r.getDouble("systolic"),r.getDouble("diastolic"));MonthPlacement.plan(Collections.emptySet(),r.getString("month"),false);require(r.optString("note").length()<=1000&&r.optString("pulseText").length()<=100&&r.optString("dayPart").length()<=50);}
  for(int i=0;i<links.length();i++){JSONObject l=links.getJSONObject(i);require(keys.contains(l.getString("key")));MonthPlacement.plan(Collections.emptySet(),l.getString("month"),false);}
  for(int i=0;i<direct.length();i++){JSONObject r=direct.getJSONObject(i);String id=r.getString("id");UUID.fromString(id);require(ids.add(id));time(r.getString("time"));pressure(r.getDouble("sys"),r.getDouble("dia"));if(!r.isNull("pulse")){double p=r.getDouble("pulse");require(Double.isFinite(p)&&p>0&&p<=400);}require(r.getInt("estimated")==0||r.getInt("estimated")==1);if(!r.isNull("status"))require(r.getInt("status")>=0&&r.getInt("status")<=65535);require(r.optString("device").length()<=200);}
  JSONObject notes=d.getJSONObject("notes");Iterator<String> it=notes.keys();while(it.hasNext()){String k=it.next();require(k.startsWith("note:"));key(k.substring(5));require(notes.get(k) instanceof String&&notes.getString(k).length()<=1000);}
  for(int i=0;i<hidden.length();i++)key(hidden.getString(i));
  for(int i=0;i<heart.length();i++){JSONObject p=heart.getJSONObject(i);time(p.getString("time"));require(p.getLong("bpm")>0&&p.getLong("bpm")<=400&&p.getString("source").length()<=200);}
  if(version==2){JSONObject settings=d.getJSONObject("settings");require(settings.getInt("fontSize")>=0&&settings.getInt("fontSize")<=2);JSONObject bluetooth=settings.getJSONObject("bluetooth");Iterator<String> names=bluetooth.keys();while(names.hasNext()){String k=names.next();Object v=bluetooth.get(k);require((k.equals("automatic")||k.startsWith("irregular:"))?v instanceof Boolean:(k.equals("device")||k.equals("name"))&&v instanceof String&&((String)v).length()<=200);}JSONObject markers=settings.getJSONObject("pcMarkers");names=markers.keys();while(names.hasNext()){String k=names.next();require(k.startsWith("pc:")&&markers.get(k) instanceof Boolean);UUID.fromString(k.substring(3));}}
 }
 public static JSONObject settings(Context c)throws Exception{JSONObject b=new JSONObject(),pc=new JSONObject();for(Map.Entry<String,?> e:c.getSharedPreferences("bluetooth",0).getAll().entrySet()){String k=e.getKey();Object v=e.getValue();if(((k.equals("automatic")||k.startsWith("irregular:"))&&v instanceof Boolean)||((k.equals("device")||k.equals("name"))&&v instanceof String))b.put(k,v);}for(Map.Entry<String,?> e:c.getSharedPreferences("pcSync",0).getAll().entrySet())if(e.getKey().startsWith("pc:")&&e.getValue() instanceof Boolean)pc.put(e.getKey(),e.getValue());return new JSONObject().put("fontSize",c.getSharedPreferences("appearance",0).getInt("fontSize",1)).put("bluetooth",b).put("pcMarkers",pc);}
 public static int restore(Context c,JSONObject d)throws Exception{validate(d,c.getPackageName());try(DirectStore direct=new DirectStore(c)){direct.getWritableDatabase();}try(DiaryArchive archive=new DiaryArchive(c)){SQLiteDatabase db=archive.getWritableDatabase();db.execSQL("CREATE TABLE IF NOT EXISTS restore_pending(id INTEGER PRIMARY KEY,payload TEXT NOT NULL)");try(Cursor check=db.rawQuery("SELECT 1 FROM restore_pending",null)){require(!check.moveToFirst());}db.execSQL("ATTACH DATABASE ? AS restore_direct",new Object[]{c.getDatabasePath("direct-readings.db").getAbsolutePath()});int added=0;try{db.beginTransaction();try{
  Set<String> fresh=new HashSet<>();JSONArray rows=d.getJSONArray("measurements");JSONObject notes=new JSONObject();Set<String> hidden=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String k=r.getString("key");boolean exists;try(Cursor q=db.rawQuery("SELECT 1 FROM entries WHERE k=?",new String[]{k})){exists=q.moveToFirst();}if(exists)continue;db.execSQL("INSERT INTO entries(k,payload) VALUES(?,?)",new Object[]{k,r.toString()});fresh.add(k);added++;notes.put("note:"+k,d.getJSONObject("notes").optString("note:"+k,r.optString("note")));}
  JSONArray links=d.getJSONArray("folders");Set<String> placed=new HashSet<>();for(int i=0;i<links.length();i++){JSONObject l=links.getJSONObject(i);String k=l.getString("key");if(fresh.contains(k)){db.execSQL("INSERT OR IGNORE INTO folders(k,month) VALUES(?,?)",new Object[]{k,l.getString("month")});placed.add(k);}}
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String k=r.getString("key");if(fresh.contains(k)&&!placed.contains(k))db.execSQL("INSERT INTO folders(k,month) VALUES(?,?)",new Object[]{k,r.getString("month")});}
  JSONArray local=d.getJSONArray("directReadings");for(int i=0;i<local.length();i++){JSONObject r=local.getJSONObject(i);String id=r.getString("id"),k=c.getPackageName()+":"+id;boolean exists;try(Cursor q=db.rawQuery("SELECT 1 FROM restore_direct.readings WHERE id=?",new String[]{id})){exists=q.moveToFirst();}if(exists)continue;db.execSQL("INSERT INTO restore_direct.readings(id,time,sys,dia,pulse,estimated,status,device) VALUES(?,?,?,?,?,?,?,?)",new Object[]{id,r.getString("time"),r.getDouble("sys"),r.getDouble("dia"),r.isNull("pulse")?null:r.getDouble("pulse"),r.getInt("estimated"),r.isNull("status")?null:r.getInt("status"),r.isNull("device")?null:r.getString("device")});if(!fresh.contains(k))added++;fresh.add(k);if(d.getJSONObject("notes").has("note:"+k))notes.put("note:"+k,d.getJSONObject("notes").getString("note:"+k));}
  JSONArray h=d.getJSONArray("hidden");for(int i=0;i<h.length();i++)if(fresh.contains(h.getString(i)))hidden.add(h.getString(i));JSONObject pending=new JSONObject().put("restoredKeys",new JSONArray(fresh)).put("notes",notes).put("hidden",new JSONArray(hidden)).put("loadedPulseValues",d.getJSONArray("loadedPulseValues"));if(d.has("settings"))pending.put("settings",d.getJSONObject("settings"));db.execSQL("INSERT INTO restore_pending(id,payload) VALUES(1,?)",new Object[]{pending.toString()});db.setTransactionSuccessful();
 }finally{db.endTransaction();}}finally{db.execSQL("DETACH DATABASE restore_direct");}return added;}}
 public static boolean finish(Context c){try(DiaryArchive archive=new DiaryArchive(c)){SQLiteDatabase db=archive.getWritableDatabase();db.execSQL("CREATE TABLE IF NOT EXISTS restore_pending(id INTEGER PRIMARY KEY,payload TEXT NOT NULL)");JSONObject p;try(Cursor q=db.rawQuery("SELECT payload FROM restore_pending WHERE id=1",null)){if(!q.moveToFirst())return true;p=new JSONObject(q.getString(0));}SharedPreferences prefs=c.getSharedPreferences("MainActivity",0);SharedPreferences.Editor edit=prefs.edit();Set<String> restored=new HashSet<>(prefs.getStringSet("restoredKeys",Collections.emptySet()));JSONArray restoredRows=p.optJSONArray("restoredKeys");if(restoredRows!=null)for(int i=0;i<restoredRows.length();i++)restored.add(restoredRows.getString(i));edit.putStringSet("restoredKeys",restored);JSONObject notes=p.getJSONObject("notes");Iterator<String> keys=notes.keys();while(keys.hasNext()){String key=keys.next();if(!prefs.contains(key))edit.putString(key,notes.getString(key));}Set<String> h=new HashSet<>(prefs.getStringSet("hidden",Collections.emptySet()));JSONArray hidden=p.getJSONArray("hidden");for(int i=0;i<hidden.length();i++)h.add(hidden.getString(i));edit.putStringSet("hidden",h);JSONArray pulses=new JSONArray(prefs.getString("restoredPulseValues","[]")),incoming=p.getJSONArray("loadedPulseValues");Set<String> seen=new HashSet<>();JSONArray merged=new JSONArray();for(JSONArray a:new JSONArray[]{pulses,incoming})for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);String id=row.getString("time")+"|"+row.getString("source")+"|"+row.getLong("bpm");if(seen.add(id))merged.put(row);}edit.putString("restoredPulseValues",merged.toString());if(!edit.commit())return false;
 if(p.has("settings")){JSONObject s=p.getJSONObject("settings");SharedPreferences appearance=c.getSharedPreferences("appearance",0);if(!appearance.contains("fontSize")&&!appearance.edit().putInt("fontSize",s.getInt("fontSize")).commit())return false;for(String name:new String[]{"bluetooth","pcMarkers"}){SharedPreferences target=c.getSharedPreferences(name.equals("pcMarkers")?"pcSync":name,0);SharedPreferences.Editor e=target.edit();JSONObject values=s.getJSONObject(name);keys=values.keys();while(keys.hasNext()){String key=keys.next();if(target.contains(key))continue;Object value=values.get(key);if(value instanceof Boolean)e.putBoolean(key,(Boolean)value);else e.putString(key,(String)value);}if(!e.commit())return false;}}
 db.delete("restore_pending","id=1",null);return true;}catch(Exception e){return false;}}
}


